def set_yaml_variable(yaml_path, var_name, var_value, yaml_user_name=None, ip=None, port=None):
    yaml_vars_per_yaml = get_yaml_vars_by_tce(ip, port)
    record_vars = yaml_vars_per_yaml.setdefault(yaml_path, {})
    robot_var_name = "${%s}" % str(var_name)
    record_var_name_vars = record_vars.setdefault(robot_var_name, {})
    if isinstance(var_value, list):
        var_value_to_save = [str(v) for v in var_value]
    else:
        var_value_to_save = [str(var_value)]
    if yaml_user_name:
        record_var_name_vars[str(yaml_user_name).strip()] = var_value_to_save
    else:
        record_var_name_vars["default"] = var_value_to_save
    print(pprint.pformat(yaml_vars_per_yaml))


def clear_yaml_variables(ip=None, port=None):
    yaml_vars_per_yaml = get_yaml_vars_by_tce(ip, port)
    yaml_vars_per_yaml.clear()


@six.add_metaclass(ABCMeta)
class SpecialValue(object):
    def __init__(self):
        self.regexp = None
        self.name = None

    @classmethod
    def is_type_of(cls, string_representation):
        if re.search(cls.regexp, string_representation):
            return True
        else:
            return False


class InRange(SpecialValue):
    regexp = re.compile(r'^IN_RANGE\((-?\d+)\s*,\s*(-?\d+)\)$')
    name = 'IN_RANGE'

    def __init__(self, string_representation):
        super(InRange, self).__init__()
        self.string_representation = string_representation
        self.match_result = re.search(InRange.regexp, self.string_representation)
        if not self.match_result:
            raise Exception('{} object could not be with string: {}'.format(InRange.name, string_representation))
        self.lower, self.upper = int(self.match_result.group(1)), int(self.match_result.group(2))

    def __eq__(self, other):
        try:
            to_compare = int(other)
        except ValueError:
            raise Exception('Could not compare non-int-like object with int range')
        if self.lower <= to_compare <= self.upper:
            return True
        else:
            return False

    def __ne__(self, other):
        return not self.__eq__(other)


class Length(SpecialValue):
    regexp = re.compile(r'^LENGTH\((\d+)\s*\)$')
    name = 'LENGTH'

    def __init__(self, string_representation):
        super(Length, self).__init__()
        self.string_representation = string_representation
        self.match_result = re.search(Length.regexp, self.string_representation)
        if not self.match_result:
            raise Exception('{} object could not be with string: {}'.format(Length.name, string_representation))
        self.length = int(self.match_result.group(1))

    def __eq__(self, other):
        try:
            to_compare = len(other)
        except TypeError:
            raise Exception('Could not compare with object without len() method support')
        if to_compare == self.length:
            return True
        else:
            return False

    def __ne__(self, other):
        return not self.__eq__(other)


class Omit(SpecialValue):
    name = 'OMIT'
    regexp = re.compile('^OMIT$')

    def __init__(self, string_representation):
        super(Omit, self).__init__()
        self.string_representation = string_representation
        self.match_result = re.search(Omit.regexp, self.string_representation)
        if not self.match_result:
            raise Exception('{} object could not be with string: {}'.format(Omit.name, string_representation))

    def __eq__(self, other):
        return True

    def __ne__(self, other):
        return not self.__eq__(other)


class BooleanString(SpecialValue):
    name = 'BOOLEAN'
    regexp = re.compile(r'^BOOLEAN\(((?:[Tt]rue)|(?:[Ff]alse))\)$')

    def __init__(self, string_representation):
        super(BooleanString, self).__init__()
        self.string_representation = string_representation
        self.match_result = re.search(BooleanString.regexp, self.string_representation)
        if not self.match_result:
            raise Exception('{} object could not be with string: {}'.format(BooleanString.name, string_representation))
        self.bool_value = True if str(self.match_result.group(1)).lower() == 'true' else False

    def __eq__(self, other):
        if isinstance(other, bool):
            return True if other == self.bool_value else False
        else:
            return False

    def __ne__(self, other):
        return not self.__eq__(other)


SPECIAL_VALUES = [Omit, InRange, Length, BooleanString]


def get_yaml_record(yaml_filepath, yaml_user_name=None, ip=None, port=None):
    '''
    to do
    '''
    if os.path.exists(yaml_filepath):
        with open(yaml_filepath) as file:
            content = file.read()
            if '$' in content:
                content = swap_vars(content, yaml_filepath, yaml_user_name, ip, port)
            yaml_record = yaml.load(content, yaml.Loader)
        print('Yaml record:\n{}'.format(json.dumps(yaml_record, indent=4)))
        return yaml_record
    else:
        raise YamlPathNotExisting('Path to yaml: {} does not exist'.format(yaml_filepath))


def swap_vars(yaml_string_content, yaml_filepath, yaml_user_name=None, ip=None, port=None):
    yaml_vars_per_yaml = get_yaml_vars_by_tce(ip, port)
    if '$' not in yaml_string_content:
        return yaml_string_content
    else:
        if yaml_filepath not in yaml_vars_per_yaml:
            raise NotSetYamlVariable('Yaml contains variables starting with $, but not values for them are set')
        yaml_value_path = 'default' if yaml_user_name is None else str(yaml_user_name).strip()
        for to_sub in yaml_vars_per_yaml[yaml_filepath]:
            if yaml_value_path not in yaml_vars_per_yaml[yaml_filepath][to_sub]:
                raise ValueNotExistingForSelectedProfile('\nValue: {}\nnot set in yaml: {}\nfor profile: {}'
                                                         .format(to_sub, yaml_filepath, yaml_value_path))
            if yaml_user_name is not None:
                user_value = yaml_vars_per_yaml[yaml_filepath][to_sub][yaml_value_path]
            else:
                user_value = yaml_vars_per_yaml[yaml_filepath][to_sub][yaml_value_path]
            for u_value in user_value:
                if to_sub in yaml_string_content:
                    yaml_string_content = yaml_string_content.replace(to_sub, u_value, 1)
                else:
                    raise NoVariableToFill('Trying to submit: {} but yaml has no {} variable left in content:\n{}'
                                           .format(to_sub, to_sub, pprint.pformat(yaml_string_content)))
        if '$' in yaml_string_content:
            raise NotAllVariablesFilledInYaml('Not all values set for yaml: {}'.format(pprint.pformat(yaml_string_content)))
        print("\nRaw yaml content for profile: {}:\n\n{}".format(yaml_value_path, yaml_string_content))

        return yaml_string_content


def validate_yaml(yaml_filepath, yaml_user_name=None, ip=None, port=None):
    try:
        get_yaml_record(yaml_filepath, yaml_user_name, ip, port)
    except Exception as e:
        raise YamlValidationError('Wrong yaml input. Follow exception: {}\nor validate via http://www.yamllint.com/'
                                  .format(e))


def is_special_value(value):
    try:
        for special in SPECIAL_VALUES:
            result = special.is_type_of(value)
            if result:
                return special
        return None
    except Exception:
        return None


def get_yaml_vars_by_tce(ip=None, port=None):
    """
    Returns queue for given TCE IP and PORT PAIR. By default queue for None values is created.
    """
    global YAML_VARS_PER_YAML
    ip = None if ip is None else str(ip)
    port = None if port is None else str(port)
    tce_by_ip = YAML_VARS_PER_YAML.setdefault(ip, {})
    yaml_vars_by_tce_ip_and_port = tce_by_ip.setdefault(port, {})
    return yaml_vars_by_tce_ip_and_port


def get_verification_queue_by_tce(ip=None, port=None):
    """
    Returns queue for given TCE IP and PORT PAIR. By default queue for None values is created.
    """
    global VERIFICATION_QUEUE
    ip = None if ip is None else str(ip)
    port = None if port is None else str(port)
    tce_by_ip = VERIFICATION_QUEUE.setdefault(ip, {})
    ver_queue_by_tce_ip_and_port = tce_by_ip.setdefault(port, [])
    return ver_queue_by_tce_ip_and_port


def add_record_for_verification(record_name, yaml_path, yaml_user_name=None, ip=None, port=None):
    """
    Add record to queue, which is further used for verification. If IP and PORT are given, record will be added for queue
    """
    record = {'name': record_name,
              'yaml': yaml_path,
              'alias': yaml_user_name}
    get_verification_queue_by_tce(ip, port).append(record)


def get_records_for_verification(ip=None, port=None):
    """
    Returns unique record names
    """
    ver_queue = get_verification_queue_by_tce(ip, port)
    print('Verification queue length: {}'.format(len(ver_queue)))
    expected_records = [item['name'] for item in ver_queue]
    expected_unique_records = list(set(expected_records))
    print('Ordered expected record list:\n{}'.format(expected_records))
    print('Expected record types:\n{}'
          .format(pprint.pformat(dict((item, expected_records.count(item)) for item in expected_unique_records))))
    if len(ver_queue) == 0:
        raise NoRecordsToVerify('Nothing to verify, please add records for verification first ')
    return copy.deepcopy(ver_queue)


def clear_verification_queue(ip=None, port=None):
    """
    Clears queue
    """
    ver_queue = get_verification_queue_by_tce(ip, port)
    print('Cleared verification queue')
    del ver_queue[:]


def _compare_lists_of_dicts(received, expected):
    received = copy.deepcopy(received)
    expected = copy.deepcopy(expected)
    # for item in received:
    #     if item in expected:
    #         expected.remove(item)
    # return True if len(expected) == 0 else False
    for item in received:
        found = False
        for e_item in expected:
            try:
                _compare_records(item, e_item)
                found = True
                break
            except Exception:
                pass
        if found and len(expected):
            expected.remove(e_item)
    return True if len(expected) == 0 else False


def _is_dict(value):
    if isinstance(value, dict):
        return True
    return False


def _list_values_are_dicts(list_to_check):
    return True if all([isinstance(item, dict) for item in list_to_check]) else False


def _format_for_exc(value):
    if _is_dict(value):
        return json.dumps(sorted(list(value.keys())))
    else:
        return value


def _compare_records(received, expected):
    if isinstance(received, list):
        if len(received) != len(expected):
            raise RecordDifferentListLength('Received list: {} has different length than '
                                            'expected: {}, {}!={}'.format(json.dumps(received),
                                                                          json.dumps(expected),
                                                                          len(received),
                                                                          len(expected)))
        else:
            if _list_values_are_dicts(received) and _list_values_are_dicts(expected):
                print('\n{}\nRecord is a list of unordered dicts, checking if ANY received matching ANY expected\n{}\n'
                      .format('#' * 80, '#' * 80))
                equal = _compare_lists_of_dicts(received, expected)
                if equal:
                    return
                else:
                    raise UnorderedListsNotMatching('Lists of dicts not equal\n'
                                                    'Received: {}\nExpected: {}'
                                                    .format(pprint.pformat(json.dumps(received)),
                                                            pprint.pformat(json.dumps(expected))))

            else:
                print('\n{}\nRecord is a ordered list of non-dict items (or not all items are dict-type) '
                      '- comparing by indexes\n{}\n'.format('#' * 80, '#' * 80))
                for item in range(0, len(received)):
                    print("{}\nindex:\n{}\nreceived:\n{}\nexpected:\n{}"
                          .format('-' * 40, item,
                                  json.dumps(received[item]),
                                  json.dumps(expected[item])))
                    _compare_records(received[item], expected[item])
    else:
        if received == expected:
            return
        elif _is_dict(received) and len(received) == len(expected) and \
                sorted(list(received.keys())) == sorted(list(expected.keys())):
            for record_top_key in received:
                print("{}\nkey:\n{}\nreceived:\n{}\nexpected:\n{}"
                      .format('-' * 40, record_top_key,
                              json.dumps(received[record_top_key]),
                              json.dumps(expected[record_top_key])))
                if expected[record_top_key] != received[record_top_key]:
                    special = is_special_value(value=str(expected[record_top_key]))
                    if special is not None:
                        print('Value for key: {} is special value: {}'.format(record_top_key, special.name))
                        if special(expected[record_top_key]) != received[record_top_key]:
                            raise RecordDifferentSpecialValues(
                                'Values for key: {} do not match.\n'
                                'Received: {}\nExpected: {}'
                                .format(record_top_key,
                                        pprint.pformat(json.dumps(received[record_top_key])),
                                        pprint.pformat(json.dumps(expected[record_top_key]))))
                    else:
                        if isinstance(expected[record_top_key], list) or isinstance(expected[record_top_key], dict):
                            _compare_records(received[record_top_key], expected[record_top_key])
                        else:
                            raise RecordDifferentValues(
                                'Values for key: {} do not match.\nReceived: {}\nExpected: {}'
                                .format(record_top_key,
                                        pprint.pformat(json.dumps(received[record_top_key])),
                                        pprint.pformat(json.dumps(expected[record_top_key]))))
        else:
            special = is_special_value(expected)
            if special is not None and special(expected) == received:
                return
            exc_type = RecordDifferentKeys if _is_dict(received) else RecordDifferentValues
            raise exc_type("\nReceived keys:\n {}\ndoes not match expected keys:\n {}"
                           .format(_format_for_exc(received), _format_for_exc(expected)))


def compare_record_with_yaml(record, yaml_filepath, yaml_user_name=None, ip=None, port=None):
    yaml_record = get_yaml_record(yaml_filepath=yaml_filepath, yaml_user_name=yaml_user_name, ip=ip, port=port)
    possible_record_upper_keys = ['data', 'data-r1']
    parsed_record = None
    for pos_key in possible_record_upper_keys:
        if pos_key in record:
            parsed_record = record.get_value_by_unique_key(pos_key)
            break
    assert parsed_record is not None, \
        'Not able to find any keys from: {} in record:\n{}'.format(possible_record_upper_keys,
                                                                   json.dumps(record, indent=4))
    print('Received record:\n{}'.format(json.dumps(parsed_record, indent=4)))
    print('Comparision started for profile: {}'.format('default' if yaml_user_name is None else str(yaml_user_name)))
    _compare_records(parsed_record, yaml_record)


def _get_conditional_verification_function_and_params(verification_condition):
    for allowed_condition_regexp in ALLOWED_VERIFICATION_CONDITIONS:
        if allowed_condition_regexp.search(verification_condition):
            function = ALLOWED_VERIFICATION_CONDITIONS[allowed_condition_regexp]['func']
            if 'no_params' not in ALLOWED_VERIFICATION_CONDITIONS[allowed_condition_regexp]:
                params = allowed_condition_regexp.findall(verification_condition)[0]
            else:
                params = None
            return function, params
    raise Exception('No function matching sentence: {}\nAllowed conditions:\n{}'
                    .format(verification_condition,
                            pprint.pformat([ALLOWED_VERIFICATION_CONDITIONS[ac]['name']
                                            for ac in ALLOWED_VERIFICATION_CONDITIONS])))
